create table public.saving_goal_recovery_plans(user_id uuid not null references auth.users(id) on delete cascade,goal_id uuid not null,months integer not null check(months=4),monthly_amount bigint not null check(monthly_amount>=0),operation_key text not null,created_at timestamptz not null default now(),primary key(user_id,goal_id),unique(user_id,operation_key),foreign key(goal_id,user_id) references public.saving_goals(id,user_id) on delete cascade);
alter table public.saving_goal_recovery_plans enable row level security;
create policy saving_goal_recovery_plans_read on public.saving_goal_recovery_plans for select to authenticated using((select auth.uid())=user_id);
revoke all on public.saving_goal_recovery_plans from public,anon,authenticated;
grant select on public.saving_goal_recovery_plans to authenticated;

create function public.create_funded_saving_goal(p_name text,p_target_amount bigint,p_target_date date,p_recurrence_unit text,p_recurrence_interval integer,p_initial_amount bigint,p_funding_mode public.saving_funding_mode,p_source_account_id uuid,p_savings_account_id uuid,p_operation_key text) returns public.saving_goals language plpgsql security definer set search_path='' as $$ declare u uuid:=auth.uid();g public.saving_goals;m public.saving_goal_mutations;begin if u is null then raise exception 'AUTH_REQUIRED' using errcode='P0001';end if;if p_initial_amount<0 or p_initial_amount>p_target_amount or char_length(coalesce(p_operation_key,''))<8 or p_initial_amount>0 and p_funding_mode is null then raise exception 'INVALID_INITIAL_FUNDING' using errcode='P0001';end if;select sg.* into g from public.saving_goal_mutations sm join public.saving_goals sg on sg.id=sm.goal_id where sm.user_id=u and sm.operation_key=p_operation_key;if found then return g;end if;g:=public.upsert_saving_goal(null,p_name,p_target_amount,p_target_date,p_recurrence_unit,p_recurrence_interval,null);if p_initial_amount>0 then g:=public.configure_saving_goal(g.id,p_funding_mode,p_source_account_id,p_savings_account_id,'NORMAL',g.version);m:=public.record_saving_goal_mutation_v3(g.id,p_source_account_id,'DEPOSIT',p_initial_amount,'Saldo awal goal',g.version,p_operation_key);select * into g from public.saving_goals where id=g.id;end if;return g;end $$;

create or replace function public.get_parser_finance_preview(p_account_id uuid,p_amount bigint,p_type public.transaction_type) returns jsonb language plpgsql security definer set search_path='' stable as $$ declare u uuid:=auth.uid();a public.accounts;locked bigint;safe bigint;goals jsonb;debts jsonb;impacts jsonb;begin if u is null then raise exception 'AUTH_REQUIRED' using errcode='P0001';end if;if p_amount<1 then raise exception 'INVALID_MONEY' using errcode='P0001';end if;select * into a from public.accounts where id=p_account_id and user_id=u and deleted_at is null;if not found then raise exception 'ACCOUNT_NOT_FOUND' using errcode='P0001';end if;select coalesce(sum(locked_amount),0) into locked from public.saving_virtual_locks where account_id=a.id and user_id=u;safe:=greatest(a.balance-locked,0);select coalesce(jsonb_agg(jsonb_build_object('goal_id',goal_id,'name',name,'amount',amount) order by rank),'[]') into impacts from(select g.id goal_id,g.name,least(v.locked_amount,greatest(p_amount-safe-coalesce(sum(v.locked_amount) over(order by case g.priority when 'LOW' then 1 when 'NORMAL' then 2 when 'HIGH' then 3 else 4 end,g.id rows between unbounded preceding and 1 preceding),0),0)) amount,row_number() over(order by case g.priority when 'LOW' then 1 when 'NORMAL' then 2 when 'HIGH' then 3 else 4 end,g.id) rank from public.saving_virtual_locks v join public.saving_goals g on g.id=v.goal_id where v.account_id=a.id and v.user_id=u)s where amount>0;select coalesce(jsonb_agg(jsonb_build_object('id',g.id,'name',g.name,'kind','GOAL','version',g.version,'maximum',g.target_amount-g.saved_amount,'recommended',least(g.target_amount-g.saved_amount,p_amount/2)) order by case g.priority when 'CRITICAL' then 1 when 'HIGH' then 2 when 'NORMAL' then 3 else 4 end,g.target_date nulls last,g.id),'[]') into goals from public.saving_goals g where g.user_id=u and g.deleted_at is null and g.lifecycle_status='ACTIVE' and g.funding_mode is not null and g.saved_amount<g.target_amount;select coalesce(jsonb_agg(jsonb_build_object('id',d.id,'name',d.name,'kind','DEBT','version',d.version,'maximum',d.total_amount-d.paid_amount,'recommended',least(d.total_amount-d.paid_amount,p_amount/4)) order by d.due_date nulls last,d.id),'[]') into debts from public.debts d where d.user_id=u and d.deleted_at is null and d.paid_amount<d.total_amount;return jsonb_build_object('gross_balance',a.balance,'protected_amount',locked,'free_balance',safe,'protected_shortfall',case when p_type='EXPENSE' then greatest(p_amount-safe,0) else 0 end,'recovery_impacts',impacts,'goals',goals,'debts',debts,'free_remainder',p_amount);end $$;

create function public.confirm_four_month_recovery(p_goal_id uuid,p_expected_version integer,p_operation_key text) returns jsonb language plpgsql security definer set search_path='' as $$ declare u uuid:=auth.uid();g public.saving_goals;monthly bigint;r public.saving_goal_recovery_plans;begin if u is null then raise exception 'AUTH_REQUIRED' using errcode='P0001';end if;select * into r from public.saving_goal_recovery_plans where user_id=u and operation_key=p_operation_key;if found then return to_jsonb(r);end if;select * into g from public.saving_goals where id=p_goal_id and user_id=u and deleted_at is null for update;if not found then raise exception 'GOAL_NOT_FOUND' using errcode='P0001';end if;if g.version<>p_expected_version then raise exception 'VERSION_CONFLICT' using errcode='P0001';end if;monthly:=ceil(greatest(g.target_amount-g.saved_amount,0)::numeric/4)::bigint;insert into public.saving_goal_recovery_plans(user_id,goal_id,months,monthly_amount,operation_key) values(u,g.id,4,monthly,p_operation_key) on conflict(user_id,goal_id) do update set months=4,monthly_amount=excluded.monthly_amount,operation_key=excluded.operation_key,created_at=now() returning * into r;return to_jsonb(r);end $$;

create function public.use_saving_goal_v2(p_goal_id uuid,p_amount bigint,p_category_id uuid,p_description text,p_note text,p_surplus_choice text,p_redirect_goal_id uuid,p_expected_version integer,p_redirect_version integer,p_operation_key text) returns public.transactions language plpgsql security definer set search_path='' as $$ declare u uuid:=auth.uid();g public.saving_goals;d public.saving_goals;a public.accounts;c public.categories;l public.saving_virtual_locks;t public.transactions;existing uuid;remainder bigint;begin if u is null then raise exception 'AUTH_REQUIRED' using errcode='P0001';end if;select transaction_id into existing from public.saving_goal_dispositions where user_id=u and operation_key=p_operation_key;if found then select * into t from public.transactions where id=existing;return t;end if;select * into g from public.saving_goals where id=p_goal_id and user_id=u and deleted_at is null for update;if not found or g.version<>p_expected_version then raise exception 'GOAL_NOT_FOUND_OR_VERSION_CONFLICT' using errcode='P0001';end if;if p_amount<1 or p_amount>g.saved_amount or p_surplus_choice not in('KEEP','REDIRECT','RELEASE') then raise exception 'INVALID_GOAL_USE' using errcode='P0001';end if;remainder:=g.saved_amount-p_amount;if remainder>0 and p_surplus_choice='REDIRECT' then select * into d from public.saving_goals where id=p_redirect_goal_id and user_id=u and deleted_at is null for update;if not found or d.version<>p_redirect_version or d.saved_amount+remainder>d.target_amount or d.funding_mode<>g.funding_mode or g.funding_mode='VIRTUAL_LOCK' and d.source_account_id<>g.source_account_id or g.funding_mode='SEPARATE_ACCOUNT' and d.savings_account_id<>g.savings_account_id then raise exception 'INVALID_REDIRECT' using errcode='P0001';end if;end if;select * into c from public.categories where id=p_category_id and user_id=u and type='EXPENSE' and deleted_at is null;if not found then raise exception 'CATEGORY_NOT_FOUND' using errcode='P0001';end if;select * into a from public.accounts where id=case when g.funding_mode='VIRTUAL_LOCK' then g.source_account_id else g.savings_account_id end and user_id=u and deleted_at is null for update;if g.funding_mode='VIRTUAL_LOCK' then select * into l from public.saving_virtual_locks where goal_id=g.id for update;if l.locked_amount<g.saved_amount then raise exception 'INSUFFICIENT_LOCK' using errcode='P0001';end if;delete from public.saving_virtual_locks where id=l.id;elsif a.balance<(p_amount+(case when p_surplus_choice='RELEASE' then remainder else 0 end)) then raise exception 'INSUFFICIENT_BALANCE' using errcode='P0001';end if;t:=public.create_money_transaction(a.id,'EXPENSE',p_amount,c.id,null,p_description,p_note,now(),'MANUAL');update public.transactions set operation_key=p_operation_key where id=t.id returning * into t;if remainder>0 and p_surplus_choice='REDIRECT' then update public.saving_goals set saved_amount=saved_amount+remainder where id=d.id;insert into public.saving_goal_mutations(user_id,goal_id,account_id,operation_key,kind,amount,note) values(u,d.id,a.id,p_operation_key||'-redirect','DEPOSIT',remainder,'Sisa penggunaan goal');if g.funding_mode='VIRTUAL_LOCK' then insert into public.saving_virtual_locks(user_id,goal_id,account_id,locked_amount) values(u,d.id,a.id,remainder) on conflict(goal_id) do update set locked_amount=public.saving_virtual_locks.locked_amount+excluded.locked_amount;end if;elsif remainder>0 and p_surplus_choice='KEEP' and g.funding_mode='VIRTUAL_LOCK' then insert into public.saving_virtual_locks(user_id,goal_id,account_id,locked_amount) values(u,g.id,a.id,remainder);end if;update public.saving_goals set saved_amount=case when p_surplus_choice='KEEP' then remainder else 0 end,lifecycle_status='ACTIVE' where id=g.id;insert into public.saving_goal_mutations(user_id,goal_id,account_id,operation_key,kind,amount,note) values(u,g.id,a.id,p_operation_key||'-use','WITHDRAWAL',p_amount,coalesce(nullif(btrim(p_note),''),'Penggunaan goal'));insert into public.saving_goal_dispositions(user_id,operation_key,goal_id,kind,transaction_id,amount) values(u,p_operation_key,g.id,'USE',t.id,p_amount);return t;end $$;

revoke execute on function public.create_funded_saving_goal(text,bigint,date,text,integer,bigint,public.saving_funding_mode,uuid,uuid,text),public.confirm_four_month_recovery(uuid,integer,text),public.use_saving_goal_v2(uuid,bigint,uuid,text,text,text,uuid,integer,integer,text) from public,anon;
grant execute on function public.create_funded_saving_goal(text,bigint,date,text,integer,bigint,public.saving_funding_mode,uuid,uuid,text),public.confirm_four_month_recovery(uuid,integer,text),public.use_saving_goal_v2(uuid,bigint,uuid,text,text,text,uuid,integer,integer,text) to authenticated;
do $$begin if has_function_privilege('anon','public.create_funded_saving_goal(text,bigint,date,text,integer,bigint,public.saving_funding_mode,uuid,uuid,text)','execute') or not has_function_privilege('authenticated','public.create_funded_saving_goal(text,bigint,date,text,integer,bigint,public.saving_funding_mode,uuid,uuid,text)','execute') then raise exception 'RPC_PRIVILEGE_CHECK_FAILED';end if;end$$;

create function public.get_salary_budget_reduction_candidate(p_amount bigint) returns jsonb language sql security definer set search_path='' stable as $$ with c as(select id,user_id,start_date,end_date,timezone from public.budget_cycles where user_id=(select auth.uid()) and status='ACTIVE' limit 1),u as(select ba.id,coalesce(sum(-t.amount),0)::bigint used from public.budget_allocations ba join c on c.id=ba.cycle_id left join public.transactions t on t.user_id=c.user_id and t.category_id=ba.category_id and t.type='EXPENSE' and t.deleted_at is null and (t.occurred_at at time zone c.timezone)::date>=c.start_date and (t.occurred_at at time zone c.timezone)::date<c.end_date where ba.deleted_at is null and ba.kind='CATEGORY' group by ba.id),r as(select ba.*,greatest(ba.allocated_amount-u.used-1,0)::bigint reducible from public.budget_allocations ba join c on c.id=ba.cycle_id join u on u.id=ba.id where ba.deleted_at is null and greatest(ba.allocated_amount-u.used-1,0)>0 order by case when lower(ba.label)~'(hiburan|entertainment|leisure|fun)' then 0 else 1 end,ba.sort_order,ba.id limit 1) select case when exists(select 1 from r) then (select jsonb_build_object('id',id,'label',label,'version',version,'remaining',allocated_amount-(select used from u where u.id=r.id),'reducible',least(reducible,greatest(p_amount,0))) from r) else null end $$;

create function public.apply_salary_budget_reduction(p_allocation_id uuid,p_expected_version integer,p_amount bigint,p_account_id uuid,p_goals jsonb,p_operation_key text) returns jsonb language plpgsql security definer set search_path='' as $$ declare u uuid:=auth.uid();a public.budget_allocations;x jsonb;g public.saving_goals;total bigint:=0;used bigint;before jsonb;begin if u is null then raise exception 'AUTH_REQUIRED' using errcode='P0001';end if;if p_amount<1 or jsonb_typeof(p_goals)<>'array' or char_length(coalesce(p_operation_key,''))<8 then raise exception 'INVALID_REDUCTION' using errcode='P0001';end if;if exists(select 1 from public.budget_allocation_events where user_id=u and note='salary-reduction:'||p_operation_key) then return jsonb_build_object('reduced',p_amount,'replayed',true);end if;select * into a from public.budget_allocations where id=p_allocation_id and user_id=u and deleted_at is null for update;if not found or a.kind<>'CATEGORY' then raise exception 'ALLOCATION_NOT_FOUND' using errcode='P0001';end if;if a.version<>p_expected_version then raise exception 'VERSION_CONFLICT' using errcode='P0001';end if;select coalesce(sum(-t.amount),0)::bigint into used from public.budget_cycles c left join public.transactions t on t.user_id=u and t.category_id=a.category_id and t.type='EXPENSE' and t.deleted_at is null and (t.occurred_at at time zone c.timezone)::date>=c.start_date and (t.occurred_at at time zone c.timezone)::date<c.end_date where c.id=a.cycle_id group by c.id;if p_amount>greatest(a.allocated_amount-coalesce(used,0)-1,0) then raise exception 'REDUCTION_EXCEEDS_REDUCIBLE' using errcode='P0001';end if;select coalesce(sum((e->>'amount')::bigint),0) into total from jsonb_array_elements(p_goals)e;if total<>p_amount then raise exception 'GOALS_MUST_EQUAL_REDUCTION' using errcode='P0001';end if;before:=to_jsonb(a);for x in select * from jsonb_array_elements(p_goals) loop select * into g from public.saving_goals where id=(x->>'id')::uuid and user_id=u and deleted_at is null and lifecycle_status='ACTIVE' for update;if not found or g.version<>(x->>'version')::integer or (x->>'amount')::bigint<1 or g.saved_amount+(x->>'amount')::bigint>g.target_amount then raise exception 'INVALID_GOAL_ALLOCATION' using errcode='P0001';end if;perform public.record_saving_goal_mutation_v3(g.id,p_account_id,'DEPOSIT',(x->>'amount')::bigint,'Pengalihan budget',g.version,p_operation_key||'-'||g.id::text);end loop;update public.budget_allocations set allocated_amount=allocated_amount-p_amount,version=version+1 where id=a.id;insert into public.budget_allocation_events(user_id,cycle_id,event_type,source_allocation_id,amount,before_state,after_state,note) values(u,a.cycle_id,'REVISED',a.id,p_amount,before,jsonb_build_object('id',a.id,'allocated_amount',a.allocated_amount-p_amount,'version',a.version+1),'salary-reduction:'||p_operation_key);return jsonb_build_object('reduced',p_amount,'replayed',false);end $$;

create function public.preview_saving_goal_deposit(p_goal_id uuid,p_amount bigint) returns jsonb language plpgsql security definer set search_path='' stable as $$ declare u uuid:=auth.uid();g public.saving_goals;accepted bigint;destinations jsonb;begin if u is null then raise exception 'AUTH_REQUIRED' using errcode='P0001';end if;if p_amount<1 then raise exception 'INVALID_MONEY' using errcode='P0001';end if;select * into g from public.saving_goals where id=p_goal_id and user_id=u and deleted_at is null and lifecycle_status in('ACTIVE','FUNDED');if not found or g.funding_mode is null then raise exception 'GOAL_NOT_CONFIGURED' using errcode='P0001';end if;accepted:=least(p_amount,g.target_amount-g.saved_amount);select coalesce(jsonb_agg(jsonb_build_object('id',d.id,'name',d.name,'version',d.version,'remaining_amount',d.target_amount-d.saved_amount) order by d.priority desc,d.target_date nulls last,d.id),'[]') into destinations from public.saving_goals d where d.user_id=u and d.id<>g.id and d.deleted_at is null and d.lifecycle_status='ACTIVE' and d.saved_amount<d.target_amount and d.funding_mode=g.funding_mode and (g.funding_mode='VIRTUAL_LOCK' and d.source_account_id=g.source_account_id or g.funding_mode='SEPARATE_ACCOUNT' and d.source_account_id=g.source_account_id and d.savings_account_id=g.savings_account_id) and d.target_amount-d.saved_amount>=p_amount-accepted;return jsonb_build_object('accepted_amount',accepted,'overflow_amount',p_amount-accepted,'destinations',destinations);end $$;

create function public.apply_saving_goal_deposit(p_goal_id uuid,p_account_id uuid,p_amount bigint,p_redirect_goal_id uuid,p_expected_version integer,p_redirect_version integer,p_note text,p_operation_key text) returns jsonb language plpgsql security definer set search_path='' as $$ declare u uuid:=auth.uid();g public.saving_goals;d public.saving_goals;accepted bigint;overflow bigint;m public.saving_goal_mutations;begin if u is null then raise exception 'AUTH_REQUIRED' using errcode='P0001';end if;select * into m from public.saving_goal_mutations where user_id=u and operation_key=p_operation_key||'-accepted';if found then return jsonb_build_object('accepted_amount',least(p_amount,(select target_amount-saved_amount+m.amount from public.saving_goals where id=p_goal_id)),'redirected_amount',case when p_redirect_goal_id is null then 0 else p_amount-m.amount end,'replayed',true);end if;select * into g from public.saving_goals where id=p_goal_id and user_id=u and deleted_at is null for update;if not found or g.version<>p_expected_version or g.funding_mode is null or p_amount<1 then raise exception 'GOAL_NOT_FOUND_OR_VERSION_CONFLICT' using errcode='P0001';end if;accepted:=least(p_amount,g.target_amount-g.saved_amount);overflow:=p_amount-accepted;if overflow>0 then select * into d from public.saving_goals where id=p_redirect_goal_id and user_id=u and deleted_at is null and lifecycle_status='ACTIVE' for update;if not found or d.version<>p_redirect_version or d.target_amount-d.saved_amount<overflow or d.funding_mode<>g.funding_mode or g.funding_mode='VIRTUAL_LOCK' and d.source_account_id<>g.source_account_id or g.funding_mode='SEPARATE_ACCOUNT' and (d.source_account_id<>g.source_account_id or d.savings_account_id<>g.savings_account_id) then raise exception 'REDIRECT_CONFIRMATION_REQUIRED' using errcode='P0001';end if;end if;if accepted>0 then perform public.record_saving_goal_mutation_v3(g.id,p_account_id,'DEPOSIT',accepted,p_note,g.version,p_operation_key||'-accepted');end if;if overflow>0 then perform public.record_saving_goal_mutation_v3(d.id,p_account_id,'DEPOSIT',overflow,p_note,d.version,p_operation_key||'-redirect');end if;return jsonb_build_object('accepted_amount',accepted,'redirected_amount',overflow,'replayed',false);end $$;

revoke execute on function public.get_salary_budget_reduction_candidate(bigint),public.apply_salary_budget_reduction(uuid,integer,bigint,uuid,jsonb,text),public.preview_saving_goal_deposit(uuid,bigint),public.apply_saving_goal_deposit(uuid,uuid,bigint,uuid,integer,integer,text,text) from public,anon;
grant execute on function public.get_salary_budget_reduction_candidate(bigint),public.apply_salary_budget_reduction(uuid,integer,bigint,uuid,jsonb,text),public.preview_saving_goal_deposit(uuid,bigint),public.apply_saving_goal_deposit(uuid,uuid,bigint,uuid,integer,integer,text,text) to authenticated;
